widget.solution:
def brier(y, p):
    return sum((pi - yi) ** 2 for yi, pi in zip(y, p)) / len(y)

def expected_calibration_error(y, p, n_bins):
    # sum over bins of (count / n) * |mean p - observed frequency|
    groups = [[] for _ in range(n_bins)]
    for yi, pi in zip(y, p):
        groups[min(int(pi * n_bins), n_bins - 1)].append((yi, pi))
    total = 0.0
    for g in groups:
        if g:
            mean_p = sum(pi for _, pi in g) / len(g)
            freq = sum(yi for yi, _ in g) / len(g)
            total += len(g) / len(y) * abs(mean_p - freq)
    return total
